// Fork of "Random Delaunay Triangulation" by tomkh. https://shadertoy.com/view/4sKyRD
// 2025-01-16 15:06:18



//===============================================================
//  Image Tab
//===============================================================

//----------------------------------------------------------
//  A) Hash & "cellPt" (balanced seeds)
//----------------------------------------------------------
vec2 hashPt(vec2 p, float timeOffset)
{
    float n = sin(dot(p, vec2(41.0, 289.0)));
    p       = fract(vec2(262144.0, 32768.0)*n);
    return sin(p * 6.2831853 + timeOffset)*0.5 + 0.5;
}

vec2 cellPt(vec2 p)
{
    return p + 0.5 + (hashPt(p, iTime) - 0.5)*0.5;
}

//----------------------------------------------------------
//  B) Voronoi distance: returns ( distToClosestSeed, distToCellBorder )
//----------------------------------------------------------
vec2 edgeVoronoi(vec2 p)
{
    vec2 pH = floor(p);

    float md = 1e10;
    vec2  mh = vec2(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++)
    {
        vec2 h = cellPt(pH + vec2(i,j)) - p;
        float d = dot(h, h);
        if(d < md)
        {
            md = d;
            mh = h;
        }
    }

    float ed = 1e10;
    const float eps = 1e-4;
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++)
    {
        vec2 h = cellPt(pH + vec2(i,j)) - p;
        // only consider edges that differ from the closest seed
        if(dot(h - mh, h - mh) > eps)
        {
            float dEdge = dot(0.5*(h + mh), normalize(h - mh));
            if(dEdge < ed) ed = dEdge;
        }
    }

    return vec2(sqrt(md), ed);
}

//----------------------------------------------------------
//  C) computeHeight => Emboss ONLY near cell border
//----------------------------------------------------------
float computeHeight(vec2 p)
{
    // purely uses Voronoi info
    vec2 ev = edgeVoronoi(p);

    // distToBorder => ev.y
    // We do NOT do a center bump. Just a slight lip near edges:
    float edgeLip = smoothstep(0.0, 0.04, ev.y)*0.3;
    return clamp(edgeLip, 0.0, 1.0);
}

//----------------------------------------------------------
//  D) Geometry helpers
//----------------------------------------------------------
float cross2D(vec2 a, vec2 b)
{
    return a.x*b.y - a.y*b.x;
}

bool insideTriangle(vec2 p, vec2 A, vec2 B, vec2 C)
{
    float c1 = cross2D(B - A, p - A);
    float c2 = cross2D(C - B, p - B);
    float c3 = cross2D(A - C, p - C);
    return (c1*c2 >= 0.0 && c2*c3 >= 0.0);
}

float lineDist(vec2 p, vec2 A, vec2 B)
{
    vec2 v = B - A;
    float t = clamp(dot(p - A, v) / dot(v,v), 0.0, 1.0);
    return length((A + v*t) - p);
}

// Random grey colors for the Delaunay triangles
vec3 randTwoColors(float seed)
{
    float rnd = fract(sin(seed)*43758.5453);
    vec3 colorA = vec3(0.110, 0.110, 0.110);
    vec3 colorB = vec3(0.071, 0.071, 0.071);
    return mix(colorA, colorB, rnd);
}

//----------------------------------------------------------
//  (NEW) Random hash for integer cell ID
//----------------------------------------------------------
float randHash(ivec2 n)
{
    // Quick hash function => random in [0..1)
    float f = sin(dot(vec2(n), vec2(37.0, 59.0))) * 43758.5453;
    return fract(f);
}

//----------------------------------------------------------
//  E) mainImage
//----------------------------------------------------------
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //-----------------------------------------
    // 1) read zoomFactor from Buffer A
    //-----------------------------------------
    float zoomFactor = texture(iChannel0, vec2(0.5, 0.5)).x;
    if (zoomFactor <= 0.0) zoomFactor = 1.0;

    //-----------------------------------------
    // 2) map fragCoord -> "world" coords
    //-----------------------------------------
    vec2 R = iResolution.xy;
    vec2 p = (fragCoord - 0.5*R) / R.y * (8.0 * zoomFactor);

    // Optional small jitter
    float amplitude = 0.01;
    p += amplitude * vec2(
        sin(iTime * 80.7),
        cos(iTime * 80.3)
    );

    //-----------------------------------------
    // 3) Build Delaunay triangles => random grey
    //    Track distance to Delaunay edges => dMin
    //-----------------------------------------
    vec3 finalColor = vec3(0.0);
    float dMin      = 9999.0;

    ivec2 cellCenter = ivec2(floor(p));
    for(int j = -1; j <= 1; j++)
    {
        for(int i = -1; i <= 1; i++)
        {
            ivec2 ij = cellCenter + ivec2(i,j);

            // corners
            vec2 h0 = cellPt(vec2(ij) + vec2(0,0)) - p;
            vec2 h1 = cellPt(vec2(ij) + vec2(1,0)) - p;
            vec2 h2 = cellPt(vec2(ij) + vec2(0,1)) - p;
            vec2 h3 = cellPt(vec2(ij) + vec2(1,1)) - p;

            // pick diagonal
            bool diag0 = (length(h0 - h3) < length(h1 - h2));

            float baseSeed = dot(vec2(ij), vec2(13.721, 29.123));
            vec3 colorA    = randTwoColors(baseSeed + 0.1);
            vec3 colorB    = randTwoColors(baseSeed + 7.9);

            if(diag0)
            {
                // Tri #1 => (h0,h1,h3)
                // Tri #2 => (h0,h2,h3)
                if(insideTriangle(vec2(0.0), h0,h1,h3))
                    finalColor = colorA;
                if(insideTriangle(vec2(0.0), h0,h2,h3))
                    finalColor = colorB;

                // track edges
                dMin = min(dMin, lineDist(vec2(0.0), h0,h1));
                dMin = min(dMin, lineDist(vec2(0.0), h1,h3));
                dMin = min(dMin, lineDist(vec2(0.0), h3,h0));
                dMin = min(dMin, lineDist(vec2(0.0), h0,h2));
                dMin = min(dMin, lineDist(vec2(0.0), h2,h3));
            }
            else
            {
                // Tri #1 => (h0,h1,h2)
                // Tri #2 => (h1,h2,h3)
                if(insideTriangle(vec2(0.0), h0,h1,h2))
                    finalColor = colorA;
                if(insideTriangle(vec2(0.0), h1,h2,h3))
                    finalColor = colorB;

                dMin = min(dMin, lineDist(vec2(0.0), h0,h1));
                dMin = min(dMin, lineDist(vec2(0.0), h1,h2));
                dMin = min(dMin, lineDist(vec2(0.0), h2,h0));
                dMin = min(dMin, lineDist(vec2(0.0), h1,h3));
                dMin = min(dMin, lineDist(vec2(0.0), h2,h3));
            }
        }
    }

    //-----------------------------------------
    // 4) Black Delaunay edges
    //-----------------------------------------
    float edgeWidth  = 0.01;
    float edgeFactor = smoothstep(0.0, edgeWidth, dMin);
    vec3 outColor    = mix(vec3(0.0), finalColor, edgeFactor);

//-----------------------------------------
// (A) Randomly lighten/darken Voronoi cells
//     (applies to the Delaunay-filled interior)
//-----------------------------------------
{
    // 1) Identify the integer “base” cell
    vec2 pH = floor(p);

    // 2) Search within a 3x3 neighborhood for the closest seed
    float md2     = 1e10;
    ivec2 bestIJ  = ivec2(0);
    for(int jj = -1; jj <= 1; jj++)
    for(int ii = -1; ii <= 1; ii++)
    {
        vec2 h = cellPt(pH + vec2(ii,jj)) - p;
        float d = dot(h, h);
        if(d < md2)
        {
            md2    = d;
            bestIJ = ivec2(ii, jj);
        }
    }

    // 3) Combine with pH for a unique cell ID
    ivec2 cellID = ivec2(floor(pH)) + bestIJ;

    // 4) Get a stable random factor in [0..1]
    float r = randHash(cellID);

    // ------------------------------------------------
    // *** CHANGED: Incorporate time to get fluctuations
    // ------------------------------------------------
    // We'll define a frequency of fluctuation and use
    // 'r' as a phase offset so each cell has a distinct wiggle.
    float freq      = 5.5;             // how fast they oscillate
    float phase     = r * 10.0;        // random offset per-cell
    float oscill    = 0.5 + 0.5 * sin(iTime * freq + phase);

    // Remap that [0..1] oscillation into a brightness range:
    float brightness = mix(0.70, 0.0, oscill);

    // 6) Apply it to the outColor of the cell
    outColor *= brightness;
}

    //-----------------------------------------
    // 5) Voronoi overlay (no center fill)
    //-----------------------------------------
    vec2 ev = edgeVoronoi(p);

    // Pink edges
    float voronoiEdgeWidth = 0.0175;
    if (ev.y < voronoiEdgeWidth)
    {
        outColor = vec3(1.000, 0.000, 0.349);
    }

    // Large glow
    {
        float glowRadius = 0.40;
        float glowFactor = 0.30
            - smoothstep(voronoiEdgeWidth, voronoiEdgeWidth + glowRadius, ev.y);
        glowFactor = max(glowFactor, 0.0);
        outColor  += vec3(1.000, 0.000, 0.349) * (glowFactor * 0.3);
    }

    // Smaller glow
    {
        float glowRadius2 = 0.20;
        float glowFactor2 = 0.30
            - smoothstep(voronoiEdgeWidth, voronoiEdgeWidth + glowRadius2, ev.y);
        glowFactor2 = max(glowFactor2, 0.0);
        outColor   += vec3(1.000, 0.000, 0.349) * (glowFactor2 * 0.1);
    }

    //-----------------------------------------
    // 7) "Echo" Voronoi => horizontal flip
    //-----------------------------------------
    vec2 p2 = p;
    p2.x = -p2.x;
    p2 *= 1.50;
    vec2 ev2 = edgeVoronoi(p2);

    float alpha2          = 0.55;   
    float smallEdgeWidth2 = 0.005;  

    // Soft edge blend
    {
        float edgeSoftRange = 0.015;
        float edgeFactor2   = 0.50
            - smoothstep(smallEdgeWidth2, smallEdgeWidth2 + edgeSoftRange, ev2.y);
        edgeFactor2 = max(edgeFactor2, 0.0);
        outColor = mix(outColor, vec3(1.000, 0.000, 0.349), alpha2 * edgeFactor2);
    }
    // Glow
    {
        float glowRadius2  = 0.2;
        float glowFactor2  = 0.50
            - smoothstep(smallEdgeWidth2, smallEdgeWidth2 + glowRadius2, ev2.y);
        glowFactor2 = max(glowFactor2, 0.0);
        outColor   += vec3(1.000, 0.000, 0.349) * (glowFactor2 * 0.3 * alpha2);
    }

    //-----------------------------------------
    // 8) Another "echo" => vertical flip
    //-----------------------------------------
    vec2 p3 = p;
    p3.y = -p3.y;
    p3 *= 2.0;
    vec2 ev3 = edgeVoronoi(p3);
    float alpha3           = 0.10;
    float smallerEdgeWidth = 0.02;

    if(ev3.y < smallerEdgeWidth)
    {
        outColor = mix(outColor, vec3(1.000, 0.000, 0.349), alpha3);
    }
    {
        float glowRadius3 = 0.2;
        float glowFactor3 = 0.50
            - smoothstep(smallerEdgeWidth, smallerEdgeWidth + glowRadius3, ev3.y);
        glowFactor3       = max(glowFactor3, 0.0);
        outColor         += vec3(1.000, 0.000, 0.349) * (glowFactor3 * 0.3 * alpha3);
    }

    //-----------------------------------------
    // 9) SPARKS along edges (optional)
    //-----------------------------------------
    {
        float edgeThreshold = 0.015;
        if(ev.y < edgeThreshold)
        {
            float speed      = 5.5;       
            float freq       = 4.5;       
            float sparkParam = fract(
                dot(p, normalize(vec2(1.0,1.0))) * freq
                - iTime*speed
            );
            float sparkDist   = abs(sparkParam - 0.5);
            float sparkFactor = smoothstep(0.1, 0.0, sparkDist);
            float borderFade  = 5.0
                - smoothstep(edgeThreshold*0.5, edgeThreshold, ev.y);
            outColor += vec3(0.2) * sparkFactor * borderFade;
        }
    }
    {
        float edgeThreshold2 = 0.015;
        if(ev2.y < edgeThreshold2)
        {
            float speed2      = 5.5;     
            float freq2       = 4.5;     
            float sparkParam2 = fract(
                dot(p2, normalize(vec2(1.0, 1.0))) * freq2
                - iTime*speed2
            );
            float sparkDist2   = abs(sparkParam2 - 0.7);
            float sparkFactor2 = smoothstep(0.05, 0.0, sparkDist2);
            float borderFade2  = 5.0
                - smoothstep(edgeThreshold2*0.5, edgeThreshold2, ev2.y);
            outColor += vec3(0.3) * sparkFactor2 * borderFade2 * 0.2;
        }
    }
    {
        float edgeThreshold3 = 0.015;
        if(ev3.y < edgeThreshold3)
        {
            float speed3      = 5.5;
            float freq3       = 4.5;
            float sparkParam3 = fract(
                dot(p3, normalize(vec2(1.0, 1.0))) * freq3
                - iTime*speed3
            );
            float sparkDist3   = abs(sparkParam3 - 0.7);
            float sparkFactor3 = smoothstep(0.05, 0.0, sparkDist3);
            float borderFade3  = 5.0
                - smoothstep(edgeThreshold3*0.5, edgeThreshold3, ev3.y);
            outColor += vec3(0.20) * sparkFactor3 * borderFade3 * 0.2;
        }
    }

    //-----------------------------------------
    // 10) Simple emboss near Voronoi edges only
    //-----------------------------------------
    {
        // Force emboss off if near a Delaunay edge => keep lines flat
        float dEdgeThreshold = 0.02; 
        float dMask          = step(dEdgeThreshold, dMin); // 1 if dMin >= threshold

        // sample height
        vec2 eps = vec2(0.001, 0.0);
        float hC = computeHeight(p)          * dMask;
        float hX = computeHeight(p + eps)    * dMask;
        float hY = computeHeight(p + eps.yx) * dMask;

        // approximate normal from cross
        vec3 dx     = vec3(eps.x, 0.0, hX - hC);
        vec3 dy     = vec3(0.0, eps.x, hY - hC);
        vec3 normal = normalize(cross(dx, dy));

        // basic lighting
        vec3 lightDir = normalize(vec3(0.5, 0.8, 1.0));
        float diff    = max(dot(normal, lightDir), 0.0);

        // spec
        vec3 halfVec  = normalize(lightDir + vec3(0.0, 0.0, 1.0));
        float spec    = pow(max(dot(normal, halfVec), 0.0), 32.0);

        // combine
        vec3 ambient  = 0.3 * outColor;
        vec3 diffuseC = 0.7 * outColor * diff;
        vec3 specular = 0.2 * spec * vec3(1.0);

        outColor = ambient + diffuseC + specular;
    }

    fragColor = vec4(outColor, 1.0);
}

//===============================================================
// Buffer A
//===============================================================
// We store (zoomFactor, direction) in RG, to oscillate between
// zoomMin and zoomMax. Larger zoomFactor => see more => "zoom out."

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Read previous frame
    vec4 old = texture(iChannel0, fragCoord / iResolution.xy);

    float zoom = old.x;
    float dir  = old.y;

    // Initialize on first frame
    if (iFrame == 0)
    {
        zoom = 1.0;  // start somewhere in the middle
        dir  = 1.0;
        // (Optionally, we could also clear iChannel0 to black in Shadertoy.)
    }

    // Range
    float zoomMin = 0.6;
    float zoomMax = 32.0;

    // 1) Figure out how far along we are between zoomMin and zoomMax
    float t = (zoom - zoomMin) / (zoomMax - zoomMin);
    t = clamp(t, 0.0, 1.0);

    // 2) Define a slow speed near zoomMin and a fast speed near zoomMax
    float slowSpeed = 0.0000030;
    float fastSpeed = 0.3;

    // 3) Interpolate speed based on t
    float dynamicRate = mix(slowSpeed, fastSpeed, t);

    // 4) Update zoom using our dynamicRate
    zoom += dir * dynamicRate;

    // 5) Flip direction if out of bounds
    if (zoom < zoomMin)
    {
        zoom = zoomMin;
        dir  = 1.0;
    }
    else if (zoom > zoomMax)
    {
        zoom = zoomMax;
        dir  = -1.0;
    }

    // Output zoom + direction
    fragColor = vec4(zoom, dir, 0.0, 1.0);
}
